  "claims": [
    {
      "id": "r:5114081037",
      "kind": "correctness",
      "harm": "test flakiness and false failures when a second rollover occurs between setting now and client idle stamping",
      "quote": "now is a whole second, taken before the clients exist and compared against an m_idle_since they stamp later, so the checks expecting a disconnect at now + timeout + 1s only hold while both fall in the same second.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "r:5122740083"
      ],
      "fix_pushed": true,
      "settled_by_id": "r:5122740083",
      "settled_by_quote": "Opted for mocking the clock and freeze it rather than trying to keep up with the current time of the actual clock as it drifts throughout the added test case."
    },
    {
      "id": "rc:3934900193",
      "kind": "approach",
      "harm": "accepted connections that send nothing prevent fast shutdown or exhaust RPC slots when -rpcservertimeout=0",
      "quote": "A connection that is accepted and never sends anything keeps m_connection_busy at its initial true, so the disconnect_all branch never picks it up. Inside ShouldDisconnect() only the idle timeout is left, and with -rpcservertimeout=0 there is no idle timeout either.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3941825335"
      ],
      "fix_pushed": false,
      "settled_by_id": "rc:3942255601",
      "settled_by_quote": "Agreed it does not belong here though, and your five seconds sounds like the right direction. Happy to open a follow-up."
    }
  ],
  "support": [
